/* @autogenerated */
import { signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { APP_CONFIG } from '../config/app-config.service';
import { emptyConfig } from '../config/app-config.model';
import { ThemeModeService } from './theme-mode.service';

const STORAGE_KEY = 'state-item-theme-mode';

describe('ThemeModeService', () => {
  const classes = () => document.documentElement.classList;

  function create(): ThemeModeService {
    const service = TestBed.inject(ThemeModeService);
    TestBed.tick();
    return service;
  }

  beforeEach(() => localStorage.removeItem(STORAGE_KEY));

  afterEach(() => {
    localStorage.removeItem(STORAGE_KEY);
    classes().remove('theme-light', 'theme-dark');
  });

  it('follows the system by default', () => {
    const service = create();
    expect(service.mode()).toBe('auto');
    expect(classes().contains('theme-light')).toBeFalse();
    expect(classes().contains('theme-dark')).toBeFalse();
  });

  it('applies the forced mode without reloading and persists it', () => {
    const service = create();

    service.mode.set('dark');
    TestBed.tick();
    expect(classes().contains('theme-dark')).toBeTrue();
    expect(classes().contains('theme-light')).toBeFalse();

    service.mode.set('light');
    TestBed.tick();
    expect(classes().contains('theme-light')).toBeTrue();
    expect(classes().contains('theme-dark')).toBeFalse();
    expect(JSON.parse(localStorage.getItem(STORAGE_KEY)!).data).toBe('light');

    service.mode.set('auto');
    TestBed.tick();
    expect(classes().contains('theme-light')).toBeFalse();
  });

  it('restores the stored mode and ignores unknown values', () => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ data: 'dark' }));
    expect(create().mode()).toBe('dark');
    expect(classes().contains('theme-dark')).toBeTrue();

    TestBed.resetTestingModule();
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ data: 'sepia' }));
    expect(create().mode()).toBe('auto');
  });

  it('uses theme.mode from the configuration until the user chooses', () => {
    TestBed.configureTestingModule({
      providers: [{ provide: APP_CONFIG, useValue: signal({ ...emptyConfig('test'), theme: { mode: 'dark' } }) }],
    });
    const service = create();
    expect(service.mode()).toBe('dark');
    expect(service.dark()).toBeTrue();

    service.mode.set('light');
    expect(service.dark()).toBeFalse();
  });
});
